entries[257619] = { ["name"] = "Gift of the Lifebinder", ["text"] = "Unlimited range\n8 sec cast\nEonar creates the Gift of the Lifebinder, a life-giving tree that springs forth to save the players. The Gift of the Lifebinder is created with several stacks of Life-Giving Roots, depending on players' raid size. Players may heal the Gift of the Lifebinder.\n\nWhile the Gift of the Lifebinder lives, players may freely Release Spirit after dying while fighting Argus and will return to the encounter space as ghosts. If players move to the tree as ghosts, they will be returned to life. However, returning to life in this way will remove a stack of Life-giving Roots. Once the Life-giving Roots are consumed, resurrecting using the Gift of the Lifebinder will cause it to suffer from Withered Roots." }
entries[257620] = { ["name"] = "Multi-Shot", ["text"] = "30 Focus 40 yd range\nInstant\nRequires Ranged Weapon\nFires several missiles, hitting your current target and all enemies within 10 yards for (50.76% of Attack Power) Physical damage. Deals reduced damage beyond 5 targets. [ Lethal Shots : Multi-Shot has a 30% chance to reduce the cooldown of Rapid Fire by 5.0 sec ]" }
